/* timerfd_example.c: Creates a non-repeating 1-second timer using timerfd_create and waits for expiration using read(). */
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main(void) {
    int tfd;
    struct itimerspec its;
    uint64_t expirations;
    ssize_t s;

    // 1. Create a timer file descriptor using the monotonic clock
    tfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (tfd == -1) {
        perror("timerfd_create");
        exit(EXIT_FAILURE);
    }

    // Configure the timer:
    // Initial expiration time: 1 second
    its.it_value.tv_sec = 1;
    its.it_value.tv_nsec = 0;
    // Interval: 0 (one-shot timer)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 0;

    // 2. Arm the timer
    if (timerfd_settime(tfd, 0, &its, NULL) == -1) {
        perror("timerfd_settime");
        close(tfd);
        exit(EXIT_FAILURE);
    }

    printf("Waiting 1 second for timer expiration...\n");

    // 3. Read from the FD to block until expiration
    s = read(tfd, &expirations, sizeof(uint64_t));
    if (s != sizeof(uint64_t)) {
        perror("read failed or partial read");
        close(tfd);
        exit(EXIT_FAILURE);
    }

    printf("Timer expired! Read %ju expirations.\n", (uintmax_t) expirations);

    // Cleanup
    close(tfd);
    return EXIT_SUCCESS;
}
